# ---- Resumen impreso en la hoja 7 ----
HOJA7 = {
 "LOGISTICS": 46038, "LOGISTICS B": 138400, "PA ABIERTA EN EL AREA DE OFICINAS": 377000,
 "PA ARCHIVE CENTER": 127480, "PA PRIVADOS": 109972, "PA WAITING AREA": 74448,
 "OFICINA CEO": 127024, "SALA DE JUNTAS": 123070, "MANTENIMIENTO": 50310,
 "LOBBY": 156090, "SERVICIO MEDICO": 28493, "OFICINAS RH": 111144,
 "METROLOGIA": 35185, "METALURGIA": 59730, "CUARENTENA": 45550,
}
SUBTOTAL_HOJA7 = 1609934

errores = []
productos = []
for hoja, partida, area, cmods, totmod, imparea, rens in D:
    suma = 0
    for grupo, desc, clave, pu, cant, sub in rens:
        if pu * cant != sub:
            errores.append(f"hoja {hoja}: {clave or desc[:30]} {pu}x{cant} != {sub}")
        suma += sub
        productos.append({
            "area": area, "partida": partida, "grupo": grupo,
            "descripcion": desc, "clave": clave,
            "precioUnitario": pu, "cantidad": cant, "subtotal": sub,
            "cantidadModulos": cmods, "totalModulo": totmod, "importeArea": imparea,
            "hoja": hoja,
        })
    if suma != totmod:
        errores.append(f"hoja {hoja} ({area}): suma renglones {suma} != Total Modulo {totmod}")
    if totmod * cmods != imparea:
        errores.append(f"hoja {hoja} ({area}): {totmod} x {cmods} != importe area {imparea}")
    if HOJA7.get(area) != imparea:
        errores.append(f"hoja 7 ({area}): resumen {HOJA7.get(area)} != importe calculado {imparea}")

total = sum(v for v in HOJA7.values())
if total != SUBTOTAL_HOJA7:
    errores.append(f"suma de las 15 areas {total} != subtotal impreso {SUBTOTAL_HOJA7}")

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sona-productos.json")
with open(out, "w", encoding="utf-8") as f:
    json.dump(productos, f, ensure_ascii=False, indent=1)

print("renglones:", len(productos))
print("suma 15 areas:", total, "| subtotal hoja 7:", SUBTOTAL_HOJA7)
print("IVA 16%:", round(total * 0.16, 2), "| total:", round(total * 1.16, 2))
print("claves distintas:", len({p["clave"] for p in productos if p["clave"]}))
print("ERRORES:", errores if errores else "ninguno")
